import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Create the scene
const scene = createScene();

// Create a container group for coordinate system conversion
// Blender uses Z-up, Three.js uses Y-up
// Apply -90 degree rotation around X-axis to convert Y-up to Z-up
const blenderContainer = new THREE.Group();
blenderContainer.rotation.x = -Math.PI / 2; // -90 degrees in radians
blenderContainer.add(scene);

// Update all matrices to apply transformations
blenderContainer.updateMatrixWorld(true);

// Function to expand InstancedMesh into regular meshes
function expandInstancedMeshes(object) {
  const meshesToAdd = [];
  const objectsToRemove = [];

  object.traverse((child) => {
    if (child instanceof THREE.InstancedMesh) {
      // Store reference to remove later
      objectsToRemove.push({ parent: child.parent, child: child });

      // Create individual meshes from instances
      const instanceCount = child.count;
      const matrix = new THREE.Matrix4();

      for (let i = 0; i < instanceCount; i++) {
        child.getMatrixAt(i, matrix);

        // Create a new mesh with the same geometry and material
        const mesh = new THREE.Mesh(child.geometry, child.material);
        mesh.name = `${child.name}_instance_${i}`;

        // Apply the instance matrix
        mesh.applyMatrix4(matrix);

        // Store for adding to the same parent
        meshesToAdd.push({ parent: child.parent, mesh: mesh });
      }
    }
  });

  // Remove InstancedMeshes
  objectsToRemove.forEach(({ parent, child }) => {
    if (parent) {
      parent.remove(child);
    }
  });

  // Add regular meshes
  meshesToAdd.forEach(({ parent, mesh }) => {
    if (parent) {
      parent.add(mesh);
    }
  });
}

// Expand any instanced meshes to regular meshes
expandInstancedMeshes(blenderContainer);

// Update world matrices again after expansion
blenderContainer.updateMatrixWorld(true);

// Create exporter
const exporter = new OBJExporter();

// Export the scene to OBJ format
const objContent = exporter.parse(blenderContainer);

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write to file
const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objContent, 'utf8');

console.log(`Successfully exported to ${outputPath}`);
console.log(`Applied -90° X-rotation for Blender Z-up coordinate system`);
console.log(`Total vertices and faces exported from the desk globe scene`);

